package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_initials_TriageGen0Test {

    @Test
    public void testInitials_NullString() {
        assertNull(WordUtils.initials(null, new char[]{',', ' '}));
    }

    @Test
    public void testInitials_EmptyString() {
        assertEquals("", WordUtils.initials("", new char[]{',', ' '}));
    }

    @Test
    public void testInitials_NullDelimiters() {
        // If delimiters is null, isDelimiter will likely return false for all chars
        // The code logic: if (delimiters != null && delimiters.length == 0) returns ""
        // If delimiters is null, it skips that block and proceeds to loop
        assertEquals("abc", WordUtils.initials("abc", null));
    }

    @Test
    public void testInitials_EmptyDelimiters() {
        assertEquals("", WordUtils.initials("abc def", new char[]{}));
    }

    @Test
    public void testInitials_StandardCase() {
        char[] delimiters = {' ', '.', ','};
        assertEquals("adf", WordUtils.initials("abc def ghi", delimiters));
    }

    @Test
    public void testInitials_MultipleDelimitersInARow() {
        char[] delimiters = {' ', '.'};
        assertEquals("ab", WordUtils.initials("a... b", delimiters));
    }

    @Test
    public void testInitials_LeadingAndTrailingDelimiters() {
        char[] delimiters = {' '};
        assertEquals("ab", WordUtils.initials(" a b ", delimiters));
    }

    @Test
    public void testInitials_NoDelimitersFound() {
        char[] delimiters = {'|'};
        assertEquals("abc", WordUtils.initials("abc", delimiters));
    }

    @Test
    public void testInitials_SingleCharacterString() {
        char[] delimiters = {' '};
        assertEquals("a", WordUtils.initials("a", delimiters));
    }

    @Test
    public void testInitials_StringWithOnlyDelimiters() {
        char[] delimiters = {' ', ','};
        assertEquals("", WordUtils.initials(" , , ", delimiters));
    }

    @Test
    public void testInitials_BufferBoundary() {
        // Testing the buf size logic: strLen / 2 + 1
        // For "a b c d", length is 7. buf size = 7/2 + 1 = 4.
        // Initials are 'a', 'b', 'c', 'd' (count = 4).
        char[] delimiters = {' '};
        assertEquals("abcd", WordUtils.initials("a b c d", delimiters));
    }
}
